(function(){
  'use strict';
  const root=document.querySelector('[data-scanner]');if(!root)return;
  const video=root.querySelector('video'),canvas=root.querySelector('canvas'),result=root.querySelector('[data-scan-result]'),status=root.querySelector('[data-status]'),start=root.querySelector('[data-start-camera]'),stop=root.querySelector('[data-stop-camera]'),upload=root.querySelector('[data-scan-upload]'),copy=root.querySelector('[data-copy-result]'),visit=root.querySelector('[data-visit-result]'),actions=root.querySelector('[data-result-actions]'),resultPlaceholder=root.querySelector('[data-result-placeholder]');
  let stream=null,raf=0,last='';
  const detector=('BarcodeDetector' in window)?new BarcodeDetector({formats:['qr_code']}):null;
  const setStatus=(m,t='')=>{status.textContent=m;status.className=`status ${t}`.trim();};
  function safeHttpUrl(value){
    const v=String(value||'').trim();
    try{const u=new URL(v);if(u.protocol==='http:'||u.protocol==='https:')return u.href;}catch{}
    if(/^www\.[^\s]+\.[a-z]{2,}(?:[/?#].*)?$/i.test(v)||/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+(?::\d+)?(?:[/?#].*)?$/i.test(v)){
      try{return new URL(`https://${v}`).href;}catch{}
    }
    return '';
  }
  const show=v=>{
    last=String(v||'').trim();
    result.textContent=last;result.hidden=false;if(resultPlaceholder)resultPlaceholder.hidden=true;
    const url=safeHttpUrl(last);
    if(actions)actions.hidden=false;
    if(copy){copy.disabled=false;copy.textContent=root.dataset.copyLabel||'Copy';}
    if(visit){
      if(url){visit.href=url;visit.hidden=false;visit.textContent=root.dataset.visit||'Visit link';}
      else{visit.hidden=true;visit.removeAttribute('href');}
    }
    setStatus(url?(root.dataset.linkReady||root.dataset.found||'Link detected.'):(root.dataset.textReady||root.dataset.found||'Text detected.'),'success');
  };
  async function detect(source){if(!detector)throw new Error(root.dataset.unsupported||'QR scanning is not supported by this browser.');const codes=await detector.detect(source);if(codes&&codes[0]&&codes[0].rawValue){show(codes[0].rawValue);return true;}return false;}
  async function tick(){if(!stream)return;try{if(video.readyState>=2&&await detect(video)){stopCamera();return;}}catch(e){setStatus(e.message||String(e),'error');stopCamera();return;}raf=requestAnimationFrame(tick);}
  async function startCamera(){
    if(!detector){setStatus(root.dataset.unsupported||'QR scanning is not supported by this browser.','error');return;}
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){setStatus(root.dataset.cameraUnsupported||'Camera access is not available.','error');return;}
    try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();start.disabled=true;stop.disabled=false;setStatus(root.dataset.scanning||'Point the camera at a QR code.');raf=requestAnimationFrame(tick);}catch(e){setStatus(root.dataset.cameraDenied||'Camera could not be opened. Check permission and HTTPS.','error');}
  }
  function stopCamera(){cancelAnimationFrame(raf);if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}video.srcObject=null;start.disabled=false;stop.disabled=true;}
  start.addEventListener('click',startCamera);stop.addEventListener('click',stopCamera);window.addEventListener('pagehide',stopCamera);
  upload.addEventListener('change',async()=>{const file=upload.files&&upload.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>8*1024*1024){setStatus(root.dataset.imageInvalid||'Choose an image under 8 MB.','error');upload.value='';return;}if(!detector){setStatus(root.dataset.unsupported||'QR scanning is not supported by this browser.','error');return;}let bmp;try{bmp=await createImageBitmap(file);canvas.width=bmp.width;canvas.height=bmp.height;canvas.getContext('2d').drawImage(bmp,0,0);const ok=await detect(canvas);if(!ok)setStatus(root.dataset.notFound||'No QR code was found in this image.','error');}catch(e){setStatus(root.dataset.notFound||'No QR code was found in this image.','error');}finally{if(bmp&&bmp.close)bmp.close();upload.value='';}});
  copy&&copy.addEventListener('click',async()=>{if(!last)return;try{await navigator.clipboard.writeText(last);setStatus(root.dataset.copied||'Copied.','success');}catch{setStatus(root.dataset.copyError||'Could not copy automatically.','error');}});
})();
